begin;
create extension if not exists pgtap with schema extensions;
set search_path=public,extensions;
select no_plan();
insert into public.tenants(id,name,slug)values('10000000-0000-4000-8000-000000226111','Dynamic Source A','dynamic-source-a'),('10000000-0000-4000-8000-000000226112','Dynamic Source B','dynamic-source-b');
create function pg_temp.source_config()returns jsonb language sql immutable as $function$select $configuration${"schemaVersion":1,"kind":"dynamic","rendererVersion":"sync-v1","sourceRevision":"8b1fdf1f8637dda23d48ecdaf08e0e5978e2707a","slideType":"sport_program","seed":{"schemaVersion":1,"rendererVersion":"sync-v1","sourceRevision":"8b1fdf1f8637dda23d48ecdaf08e0e5978e2707a","family":"fixtures","orientation":"landscape","theme":"fieldflow","name":"Gekoppeld bronontwerp","club":{"name":"Source A","tagline":""},"title":"DIT IS ONZE TROTS","headline":"","body":"","subtitle":"","topLabel":"CLUB TV","footer":"","footerRight":"","rows":[],"rowsPerPage":4,"ownRowIndexes":[],"category":"","subline":"","lineup":[],"news":[],"imageCaption":"","state":"ready","style":{"motion":"geen","background":"stadium","backgroundPosition":"center","font":"Inter, sans-serif","fontChanged":false,"accent":"#1763ed","alignment":"left","scale":100,"safeMargin":5,"showLogo":true,"showFooter":true}},"secondsPerPage":3}$configuration$::jsonb$function$;
select lives_ok($$select private.assert_sync_dynamic_configuration_v1('10000000-0000-4000-8000-000000226111','sport_program','landscape',pg_temp.source_config())$$,'a static Source seed with actual Source identity is admitted');
select throws_ok($$select private.assert_sync_dynamic_configuration_v1('10000000-0000-4000-8000-000000226111','sport_results','landscape',pg_temp.source_config())$$,'23514',null,'the configuration cannot masquerade as another canonical source type');
select throws_ok($$select private.assert_sync_dynamic_configuration_v1('10000000-0000-4000-8000-000000226111','sport_program','portrait',pg_temp.source_config())$$,'23514',null,'the source render cannot change orientation outside its authored version');
select throws_ok($$select private.assert_sync_dynamic_configuration_v1('10000000-0000-4000-8000-000000226111','sport_program','landscape',jsonb_set(pg_temp.source_config(),'{seed,rows}','[["Niet opgehaald","Voorbeeld","9","0"]]'))$$,'23514',null,'manually supplied provider facts are rejected');
select throws_ok($$select private.assert_sync_dynamic_configuration_v1('10000000-0000-4000-8000-000000226111','sport_program','landscape',jsonb_set(pg_temp.source_config(),'{seed,state}','"empty"'))$$,'23514',null,'provider status is derived rather than authored in the seed');
select throws_ok($$select private.assert_sync_dynamic_configuration_v1('10000000-0000-4000-8000-000000226111','sport_program','landscape',jsonb_set(pg_temp.source_config(),'{seed,family}','"rss"'))$$,'23514',null,'the family is scoped to the selected canonical type');
select throws_ok($$select private.assert_sync_dynamic_configuration_v1('10000000-0000-4000-8000-000000226111','sport_program','landscape',jsonb_set(pg_temp.source_config(),'{secondsPerPage}','2'))$$,'23514',null,'a page cannot fall below the complete playback minimum');
select throws_ok($$select private.assert_sync_dynamic_configuration_v1('10000000-0000-4000-8000-000000226111','sport_program','landscape',jsonb_set(pg_temp.source_config(),'{rendererVersion}','"sites-v17"'))$$,'23514',null,'a historical renderer identity is never relabelled as Source');
select is(private.json_has_sites_authoring_v1(jsonb_build_object('syncConfiguration',pg_temp.source_config())),true,'the existing authoring pause recognizes the new configuration');
insert into public.media_assets(id,tenant_id,kind,title,original_file_name,mime_type,status,storage_path,file_size_bytes,checksum_sha256,width,height)values('20000000-0000-4000-8000-000000226112','10000000-0000-4000-8000-000000226112','image','Private B','b.png','image/png','ready','tenants/10000000-0000-4000-8000-000000226112/assets/20000000-0000-4000-8000-000000226112/original/b.png',100,repeat('b',64),320,180);
insert into public.media_variants(tenant_id,asset_id,variant_type,storage_path,mime_type,file_size_bytes,checksum_sha256,width,height)values('10000000-0000-4000-8000-000000226112','20000000-0000-4000-8000-000000226112','original','tenants/10000000-0000-4000-8000-000000226112/assets/20000000-0000-4000-8000-000000226112/original/b.png','image/png',100,repeat('b',64),320,180);
select throws_ok($$select private.assert_sync_dynamic_configuration_v1('10000000-0000-4000-8000-000000226111','sport_program','landscape',jsonb_set(pg_temp.source_config(),'{seed,club,logo}',jsonb_build_object('kind','tenant','mediaAssetId','20000000-0000-4000-8000-000000226112','checksumSha256',repeat('b',64))))$$,'23514',null,'tenant A cannot supply the private image of tenant B as Source branding');
select is(has_function_privilege('authenticated','private.assert_sync_dynamic_configuration_v1(uuid,text,text,jsonb)','EXECUTE'),false,'the Source asset authority is not a public validator endpoint');
select is(has_function_privilege('anon','private.sync_dynamic_configuration_schema_v1()','EXECUTE'),false,'anonymous calls do not expose private authoring helpers');
select *from finish();rollback;
